<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Annuaire enseignants — EduVac Pro</title><style>body{font-family:system-ui;background:#f4f6f8;color:#17212b}.wrap{max-width:1100px;margin:35px auto;padding:0 18px}.card{background:white;border:1px solid #e1e7ed;border-radius:12px;padding:20px;margin:14px 0}.filters,.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}input,select{width:100%;box-sizing:border-box;padding:10px;border:1px solid #cbd5df;border-radius:8px}button{background:#176b55;color:white;padding:11px 16px;border:0;border-radius:8px}.tag{display:inline-block;background:#edf3f5;padding:5px 9px;border-radius:20px;margin:3px}</style></head><body><main class="wrap"><h1>Annuaire des enseignants</h1><p>Consultez les profils vérifiés et disponibles.</p><form class="card" method="GET"><div class="filters"><input name="q" value="{{ request('q') }}" placeholder="Nom ou ville"><select name="subject_id"><option value="">Toutes les matières</option>@foreach($subjects as $s)<option value="{{ $s->id }}" @selected(request('subject_id')==$s->id)>{{ $s->name }}</option>@endforeach</select><select name="school_level_id"><option value="">Tous les niveaux</option>@foreach($schoolLevels as $l)<option value="{{ $l->id }}" @selected(request('school_level_id')==$l->id)>{{ $l->name }}</option>@endforeach</select><input name="city" value="{{ request('city') }}" placeholder="Ville / quartier"><input type="number" min="0" name="min_experience" value="{{ request('min_experience') }}" placeholder="Expérience min. (années)"></div><p><button>Filtrer les profils</button></p></form>
